/// Media direction.
enum pjmedia_dir {
  /// None
  PJMEDIA_DIR_NONE(0),

  /// Encoding (outgoing to network) stream, also known as capture
  PJMEDIA_DIR_ENCODING(1),

  /// Decoding (incoming from network) stream, also known as playback.
  PJMEDIA_DIR_DECODING(2),

  /// Incoming and outgoing stream, same as PJMEDIA_DIR_CAPTURE_PLAYBACK
  PJMEDIA_DIR_ENCODING_DECODING(3);

  /// Same as encoding direction.
  static const PJMEDIA_DIR_CAPTURE = PJMEDIA_DIR_ENCODING;

  /// Same as decoding.
  static const PJMEDIA_DIR_PLAYBACK = PJMEDIA_DIR_DECODING;

  /// Same as decoding.
  static const PJMEDIA_DIR_RENDER = PJMEDIA_DIR_DECODING;

  /// Same as ENCODING_DECODING
  static const PJMEDIA_DIR_CAPTURE_PLAYBACK = PJMEDIA_DIR_ENCODING_DECODING;

  /// Same as ENCODING_DECODING
  static const PJMEDIA_DIR_CAPTURE_RENDER = PJMEDIA_DIR_ENCODING_DECODING;

  final int value;

  const pjmedia_dir(this.value);

  static pjmedia_dir fromValue(int value) => switch (value) {
    0 => PJMEDIA_DIR_NONE,
    1 => PJMEDIA_DIR_ENCODING,
    2 => PJMEDIA_DIR_DECODING,
    3 => PJMEDIA_DIR_ENCODING_DECODING,
    _ => throw ArgumentError('Unknown value for pjmedia_dir: $value'),
  };

  @override
  String toString() {
    if (this == PJMEDIA_DIR_ENCODING)
      return "pjmedia_dir.PJMEDIA_DIR_ENCODING, pjmedia_dir.PJMEDIA_DIR_CAPTURE";
    if (this == PJMEDIA_DIR_DECODING)
      return "pjmedia_dir.PJMEDIA_DIR_DECODING, pjmedia_dir.PJMEDIA_DIR_PLAYBACK, pjmedia_dir.PJMEDIA_DIR_RENDER";
    if (this == PJMEDIA_DIR_ENCODING_DECODING)
      return "pjmedia_dir.PJMEDIA_DIR_ENCODING_DECODING, pjmedia_dir.PJMEDIA_DIR_CAPTURE_PLAYBACK, pjmedia_dir.PJMEDIA_DIR_CAPTURE_RENDER";
    return super.toString();
  }
}

/// Enumeration of RTCP Feedback types. Each feedback type may have subtypes,
