/// This enumeration specifies the usage of SIP Session Timers extension.
enum pjsua_sip_timer_use {
  /// When this flag is specified, Session Timers will not be used in any
  /// session, except it is explicitly required in the remote request.
  PJSUA_SIP_TIMER_INACTIVE(0),

  /// When this flag is specified, Session Timers will be used in all
  /// sessions whenever remote supports and uses it.
  PJSUA_SIP_TIMER_OPTIONAL(1),

  /// When this flag is specified, Session Timers support will be
  /// a requirement for the remote to be able to establish a session.
  PJSUA_SIP_TIMER_REQUIRED(2),

  /// When this flag is specified, Session Timers will always be used
  /// in all sessions, regardless whether remote supports/uses it or not.
  PJSUA_SIP_TIMER_ALWAYS(3);

  final int value;

  const pjsua_sip_timer_use(this.value);

  static pjsua_sip_timer_use fromValue(int value) => switch (value) {
    0 => PJSUA_SIP_TIMER_INACTIVE,
    1 => PJSUA_SIP_TIMER_OPTIONAL,
    2 => PJSUA_SIP_TIMER_REQUIRED,
    3 => PJSUA_SIP_TIMER_ALWAYS,
    _ => throw ArgumentError('Unknown value for pjsua_sip_timer_use: $value'),
  };
}

/// This enumeration specifies the usage of SIPREC extension.
enum pjsua_sip_siprec_use {
  /// When this flag is specified, when a SIPREC request is received, it
  /// returns bad extension error. and SIPREC calls will not be established.
  PJSUA_SIP_SIPREC_INACTIVE(0),

  /// When this flag is specified, when you want both regular calls and
  /// SIPREC calls to be established.
  PJSUA_SIP_SIPREC_OPTIONAL(1),

  /// When this flag is specified, when you want only SIPREC calls to
  /// be established, and regular calls are rejected.
  PJSUA_SIP_SIPREC_MANDATORY(2);

  final int value;

  const pjsua_sip_siprec_use(this.value);

  static pjsua_sip_siprec_use fromValue(int value) => switch (value) {
    0 => PJSUA_SIP_SIPREC_INACTIVE,
    1 => PJSUA_SIP_SIPREC_OPTIONAL,
    2 => PJSUA_SIP_SIPREC_MANDATORY,
    _ => throw ArgumentError('Unknown value for pjsua_sip_siprec_use: $value'),
  };
}

/// This constants controls the use of 100rel extension.
enum pjsua_100rel_use {
  /// Not used. For UAC, support for 100rel will be indicated in Supported
  /// header so that peer can opt to use it if it wants to. As UAS, this
  /// option will NOT cause 100rel to be used even if UAC indicates that
