  /// option will cause 100rel to be used if UAC indicates that it supports it.
  PJSUA_100REL_OPTIONAL(2);

  final int value;

  const pjsua_100rel_use(this.value);

  static pjsua_100rel_use fromValue(int value) => switch (value) {
    0 => PJSUA_100REL_NOT_USED,
    1 => PJSUA_100REL_MANDATORY,
    2 => PJSUA_100REL_OPTIONAL,
    _ => throw ArgumentError('Unknown value for pjsua_100rel_use: $value'),
  };
}

