/// Entropy enumeration
enum pj_ssl_entropy {
  /// < None
  PJ_SSL_ENTROPY_NONE(0),

  /// < EGD
  PJ_SSL_ENTROPY_EGD(1),

  /// < Random
  PJ_SSL_ENTROPY_RANDOM(2),

  /// < Urandom
  PJ_SSL_ENTROPY_URANDOM(3),

  /// < File
  PJ_SSL_ENTROPY_FILE(4),

  /// < Unknown
  PJ_SSL_ENTROPY_UNKNOWN(15);

  final int value;

  const pj_ssl_entropy(this.value);

  static pj_ssl_entropy fromValue(int value) => switch (value) {
    0 => PJ_SSL_ENTROPY_NONE,
    1 => PJ_SSL_ENTROPY_EGD,
    2 => PJ_SSL_ENTROPY_RANDOM,
    3 => PJ_SSL_ENTROPY_URANDOM,
    4 => PJ_SSL_ENTROPY_FILE,
    15 => PJ_SSL_ENTROPY_UNKNOWN,
    _ => throw ArgumentError('Unknown value for pj_ssl_entropy: $value'),
  };
}

/// High level traffic classification.
enum pj_qos_type {
  /// < Best effort traffic (default value).
  /// Any QoS function calls with specifying
  /// this value are effectively no-op
  PJ_QOS_TYPE_BEST_EFFORT(0),

  /// < Background traffic.
  PJ_QOS_TYPE_BACKGROUND(1),

  /// < Video traffic.
  PJ_QOS_TYPE_VIDEO(2),

  /// < Voice traffic.
  PJ_QOS_TYPE_VOICE(3),

  /// < Control traffic.
  PJ_QOS_TYPE_CONTROL(4),

  /// < Signalling traffic.
  PJ_QOS_TYPE_SIGNALLING(5);

  final int value;

  const pj_qos_type(this.value);

  static pj_qos_type fromValue(int value) => switch (value) {
    0 => PJ_QOS_TYPE_BEST_EFFORT,
    1 => PJ_QOS_TYPE_BACKGROUND,
    2 => PJ_QOS_TYPE_VIDEO,
    3 => PJ_QOS_TYPE_VOICE,
    4 => PJ_QOS_TYPE_CONTROL,
    5 => PJ_QOS_TYPE_SIGNALLING,
    _ => throw ArgumentError('Unknown value for pj_qos_type: $value'),
  };
}

/// Standard WMM priorities.
enum pj_qos_wmm_prio {
