  /// This flag is only valid for #pjsua_call_reinvite() and
  /// #pjsua_call_update(). Note: for compatibility reason, this flag must
  /// have value of 1 because previously the unhold option is specified as
  /// boolean value.
  PJSUA_CALL_UNHOLD(1),

