    1 => PJSUA_CALL_UNHOLD,
    2 => PJSUA_CALL_UPDATE_CONTACT,
    4 => PJSUA_CALL_INCLUDE_DISABLED_MEDIA,
    8 => PJSUA_CALL_NO_SDP_OFFER,
    16 => PJSUA_CALL_REINIT_MEDIA,
    32 => PJSUA_CALL_UPDATE_VIA,
    64 => PJSUA_CALL_UPDATE_TARGET,
    128 => PJSUA_CALL_SET_MEDIA_DIR,
    256 => PJSUA_CALL_NO_MEDIA_SYNC,
