  /// be paused in TX direction, causing it to stop sending any video
  /// packets. No re-INVITE/UPDATE is to be transmitted to remote
  /// with this operation.
  PJSUA_CALL_VID_STRM_STOP_TRANSMIT(6),

  /// Send keyframe in the video stream. This will force the stream to
  /// generate and send video keyframe as soon as possible. No
  /// re-INVITE/UPDATE is to be transmitted to remote with this operation.
  PJSUA_CALL_VID_STRM_SEND_KEYFRAME(7);

  final int value;

  const pjsua_call_vid_strm_op(this.value);

  static pjsua_call_vid_strm_op fromValue(int value) => switch (value) {
    0 => PJSUA_CALL_VID_STRM_NO_OP,
    1 => PJSUA_CALL_VID_STRM_ADD,
    2 => PJSUA_CALL_VID_STRM_REMOVE,
    3 => PJSUA_CALL_VID_STRM_CHANGE_DIR,
    4 => PJSUA_CALL_VID_STRM_CHANGE_CAP_DEV,
    5 => PJSUA_CALL_VID_STRM_START_TRANSMIT,
    6 => PJSUA_CALL_VID_STRM_STOP_TRANSMIT,
    7 => PJSUA_CALL_VID_STRM_SEND_KEYFRAME,
    _ => throw ArgumentError(
      'Unknown value for pjsua_call_vid_strm_op: $value',
    ),
